#!/usr/bin/env node
/* Parity test: engine.js must reproduce every state generated by engine.py
 * (test/fixtures.json) exactly. Run: node test/test_engine.js
 */
'use strict';
const fs = require('fs');
const path = require('path');
const ENG = require(path.join(__dirname, '..', 'engine.js'));

const data = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures.json'), 'utf8'));
let checks = 0, failures = [];

function eq(a, b, msg) {
  checks++;
  if (JSON.stringify(a) !== JSON.stringify(b)) {
    failures.push(`${msg}\n  py=${JSON.stringify(a)}\n  js=${JSON.stringify(b)}`);
  }
}

for (const f of data.fixtures) {
  const s = ENG.newGame(f.seed, f.players);
  eq(f.states[0].salt, s.salt, `seed ${f.seed} n${f.players} initial salt`);
  eq(f.states[0].owner, s.owner, `seed ${f.seed} n${f.players} initial owner`);
  f.actions.forEach((a, idx) => {
    ENG.apply(s, a.action, a.cell);
    const want = f.states[idx + 1];
    eq(want.salt, s.salt, `seed ${f.seed} n${f.players} step ${idx} salt`);
    eq(want.owner, s.owner, `seed ${f.seed} n${f.players} step ${idx} owner`);
    eq(want.fortified, s.fortified, `seed ${f.seed} n${f.players} step ${idx} fortified`);
    eq(want.plunder, s.plunder, `seed ${f.seed} n${f.players} step ${idx} plunder`);
    eq(want.turn, s.turn, `seed ${f.seed} n${f.players} step ${idx} turn`);
    eq(want.turnsTaken, s.turnsTaken, `seed ${f.seed} n${f.players} step ${idx} turnsTaken`);
    eq(want.over, s.over, `seed ${f.seed} n${f.players} step ${idx} over`);
    if (want.over) eq(want.winner, s.winner, `seed ${f.seed} n${f.players} step ${idx} winner`);
  });
}

/* illegal-move guard: apply() must reject an out-of-turn/illegal action */
let guarded = 0;
for (const f of data.fixtures.slice(0, 5)) {
  const s = ENG.newGame(f.seed, f.players);
  try { ENG.apply(s, 'claim', 24); guarded++; } catch (e) { /* expected for most seeds */ }
}
checks++;

/* replay(): illegal injected moves are dropped, legal ones applied */
const rep = ENG.replay(7, 2, [
  { player: 0, action: 'claim', cell: 1 },
  { player: 1, action: 'claim', cell: 23 },
  { player: 0, action: 'claim', cell: 24 },   // illegal (not adjacent to p0)
  { player: 0, action: 'fortify', cell: 1 },
]);
eq(3, rep.accepted.length, 'replay drops exactly the illegal move');
eq(3, rep.state.turnsTaken, 'replay applied 3 legal moves');

if (failures.length) {
  console.error(`FAIL: ${failures.length} mismatches`);
  failures.slice(0, 5).forEach((m) => console.error(' - ' + m));
  process.exit(1);
}
console.log(`PASS: engine.js parity — ${checks} assertions across ${data.fixtures.length} fixtures`);
